// Package toml parses TOML documents into the decoder's tagged JSON model.
package toml

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Value is a scalar TOML value represented in the JSON contract.
type Value struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}

// Document is the root TOML table.
type Document map[string]any

// Decode parses a TOML document and returns its tagged representation.
func Decode(input string) (Document, error) {
	if !utf8.ValidString(input) {
		return nil, fmt.Errorf("invalid UTF-8")
	}
	for i, r := range input {
		if r == '\r' && (i+1 == len(input) || input[i+1] != '\n') {
			return nil, fmt.Errorf("invalid carriage return")
		}
		if (r < 0x20 && r != '\t' && r != '\n' && r != '\r') || r == 0x7f {
			return nil, fmt.Errorf("invalid control character")
		}
	}
	doc := make(Document)
	pos, line := 0, 1
	for {
		for pos < len(input) && (input[pos] == ' ' || input[pos] == '\t' || input[pos] == '\r' || input[pos] == '\n') {
			if input[pos] == '\n' {
				line++
			}
			pos++
		}
		if pos == len(input) {
			return doc, nil
		}
		if input[pos] == '#' {
			if end := strings.IndexByte(input[pos:], '\n'); end >= 0 {
				pos += end + 1
				line++
				continue
			}
			return doc, nil
		}
		if input[pos] == '[' {
			return nil, fmt.Errorf("line %d: tables are not implemented", line)
		}
		eq := findEquals(input, pos)
		if eq < 0 {
			return nil, fmt.Errorf("line %d: expected key and value", line)
		}
		key := trimHSpace(input[pos:eq])
		if !validBareKey(key) {
			return nil, fmt.Errorf("line %d: invalid key", line)
		}
		if _, exists := doc[key]; exists {
			return nil, fmt.Errorf("line %d: duplicate key %q", line, key)
		}
		value, end, err := parseValue(input, eq+1)
		if err != nil {
			return nil, fmt.Errorf("line %d: %w", line, err)
		}
		if trailing := trimHSpace(input[end:lineEnd(input, end)]); trailing != "" && !strings.HasPrefix(trailing, "#") {
			return nil, fmt.Errorf("line %d: trailing content", line)
		}
		doc[key] = value
		end = lineEnd(input, end)
		if end == len(input) {
			return doc, nil
		}
		pos = end + 1
		line++
	}
}

func findEquals(s string, start int) int {
	for i := start; i < len(s); i++ {
		switch s[i] {
		case '=', '\n':
			if s[i] == '=' {
				return i
			}
			return -1
		case '"', '\'':
			quote := s[i]
			if i+2 < len(s) && s[i:i+3] == string([]byte{quote, quote, quote}) {
				quote = 0
				i += 2
			}
			for i++; i < len(s); i++ {
				if quote == '"' && s[i] == '\\' {
					i++
					continue
				}
				if quote != 0 && s[i] == quote {
					break
				}
			}
		}
	}
	return -1
}

func validBareKey(key string) bool {
	if key == "" {
		return false
	}
	for _, r := range key {
		if !(r == '_' || r == '-' || r >= 'A' && r <= 'Z' || r >= 'a' && r <= 'z' || r >= '0' && r <= '9') {
			return false
		}
	}
	return true
}

func lineEnd(s string, pos int) int {
	if n := strings.IndexByte(s[pos:], '\n'); n >= 0 {
		return pos + n
	}
	return len(s)
}

func parseValue(s string, pos int) (Value, int, error) {
	for pos < len(s) && (s[pos] == ' ' || s[pos] == '\t') {
		pos++
	}
	if pos >= len(s) {
		return Value{}, pos, fmt.Errorf("missing value")
	}
	if strings.HasPrefix(s[pos:], "\"\"\"") {
		v, end, err := parseMultilineBasic(s, pos)
		return Value{"string", v}, end, err
	}
	if strings.HasPrefix(s[pos:], "'''") {
		v, end, err := parseMultilineLiteral(s, pos)
		return Value{"string", v}, end, err
	}
	if s[pos] == '"' {
		v, end, err := parseBasic(s, pos)
		return Value{"string", v}, end, err
	}
	if s[pos] == '\'' {
		v, end, err := parseLiteral(s, pos)
		return Value{"string", v}, end, err
	}
	end := pos
	for end < len(s) && s[end] != '\n' && s[end] != '#' {
		end++
	}
	raw := trimHSpace(s[pos:end])
	v, _, err := parseScalar(raw)
	return v, end, err
}

func trimHSpace(s string) string { return strings.Trim(s, " \t\r") }

func parseBasic(s string, pos int) (string, int, error)   { return parseQuoted(s, pos, '"', false) }
func parseLiteral(s string, pos int) (string, int, error) { return parseQuoted(s, pos, '\'', false) }

func parseQuoted(s string, pos int, quote byte, multi bool) (string, int, error) {
	var b strings.Builder
	for i := pos + 1; i < len(s); i++ {
		c := s[i]
		if c == quote {
			return b.String(), i + 1, nil
		}
		if c == '\n' || c == '\r' {
			return "", i, fmt.Errorf("unterminated string")
		}
		if quote == '\'' {
			b.WriteByte(c)
			continue
		}
		if c == '\\' {
			v, n, err := escape(s, i+1)
			if err != nil {
				return "", i, err
			}
			b.WriteString(v)
			i = n
			continue
		}
		if c < 0x20 || c == 0x7f {
			return "", i, fmt.Errorf("invalid control character in string")
		}
		_, n := utf8.DecodeRuneInString(s[i:])
		b.WriteString(s[i : n+i])
		i += n - 1
	}
	return "", len(s), fmt.Errorf("unterminated string")
}

func escape(s string, i int) (string, int, error) {
	if i >= len(s) {
		return "", i, fmt.Errorf("invalid escape")
	}
	short := map[byte]string{'b': "\b", 't': "\t", 'n': "\n", 'f': "\f", 'r': "\r", '"': "\"", '\\': "\\"}
	if v, ok := short[s[i]]; ok {
		return v, i, nil
	}
	n := 4
	if s[i] == 'U' {
		n = 8
	} else if s[i] != 'u' {
		return "", i, fmt.Errorf("invalid escape")
	}
	if i+n >= len(s) {
		return "", i, fmt.Errorf("invalid Unicode escape")
	}
	code, err := strconv.ParseUint(s[i+1:i+n+1], 16, 32)
	if err != nil || code > utf8.MaxRune || code >= 0xd800 && code <= 0xdfff {
		return "", i, fmt.Errorf("invalid Unicode escape")
	}
	return string(rune(code)), i + n, nil
}

func parseMultilineBasic(s string, pos int) (string, int, error) { return parseMultiline(s, pos, '"') }
func parseMultilineLiteral(s string, pos int) (string, int, error) {
	return parseMultiline(s, pos, '\'')
